-- Intake cell (intake), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA intake;

CREATE FUNCTION intake.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE intake.sources (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    source_key               text NOT NULL CHECK (length(source_key) <= 64 AND length(source_key) >= 1),
    display_name             text NOT NULL CHECK (length(display_name) <= 160 AND length(display_name) >= 1),
    source_kind              text NOT NULL CHECK (source_kind IN ('manual', 'file', 'api', 'webhook', 'email', 'calendar', 'database', 'application', 'other')),
    provider                 text CHECK (provider IS NULL OR (length(provider) <= 200)),
    domain                   text NOT NULL CHECK (length(domain) <= 80 AND length(domain) >= 1),
    dataset                  text NOT NULL CHECK (length(dataset) <= 120 AND length(dataset) >= 1),
    owner_scope              text NOT NULL DEFAULT 'solo_empire' CHECK (owner_scope IN ('personal', 'solo_empire', 'venture', 'client', 'shared')),
    privacy_class            text NOT NULL DEFAULT 'private' CHECK (privacy_class IN ('public', 'internal', 'private', 'restricted')),
    retention_class          text NOT NULL DEFAULT 'operational' CHECK (length(retention_class) <= 64),
    ingest_mode              text NOT NULL DEFAULT 'manual' CHECK (ingest_mode IN ('manual', 'batch', 'stream', 'webhook')),
    status                   text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned', 'active', 'paused', 'retired')),
    description              text,
    last_ingested_at         timestamptz,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, source_key)
);
CREATE UNIQUE INDEX sources_legacy ON intake.sources (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX sources_dataset ON intake.sources (workspace_id, dataset);
CREATE INDEX sources_domain ON intake.sources (workspace_id, domain);
CREATE INDEX sources_source_key ON intake.sources (workspace_id, source_key);
CREATE INDEX sources_source_kind ON intake.sources (workspace_id, source_kind);
CREATE INDEX sources_status ON intake.sources (workspace_id, status);

CREATE TABLE intake.intakes (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    intake_key               text NOT NULL CHECK (length(intake_key) <= 96 AND length(intake_key) >= 1),
    source_id                bigint NOT NULL,
    domain                   text NOT NULL CHECK (length(domain) <= 80 AND length(domain) >= 1),
    dataset                  text NOT NULL CHECK (length(dataset) <= 120 AND length(dataset) >= 1),
    schema_version           text NOT NULL DEFAULT '1' CHECK (length(schema_version) <= 32),
    payload_kind             text NOT NULL CHECK (payload_kind IN ('json', 'jsonl', 'csv', 'binary', 'markdown', 'parquet', 'other')),
    input_ref                text NOT NULL CHECK (length(input_ref) <= 240 AND length(input_ref) >= 1),
    source_batch_ref         text CHECK (source_batch_ref IS NULL OR (length(source_batch_ref) <= 160)),
    idempotency_key          text NOT NULL CHECK (length(idempotency_key) <= 160 AND length(idempotency_key) >= 1),
    privacy_class            text NOT NULL DEFAULT 'private' CHECK (privacy_class IN ('public', 'internal', 'private', 'restricted')),
    retention_class          text NOT NULL DEFAULT 'operational' CHECK (length(retention_class) <= 64),
    requested_by             text NOT NULL DEFAULT 'human' CHECK (requested_by IN ('human', 'agent', 'automation')),
    status                   text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'processing', 'landed', 'verified', 'rejected', 'failed', 'cancelled')),
    requested_at             timestamptz,
    claimed_at               timestamptz,
    lease_owner              text CHECK (lease_owner IS NULL OR (length(lease_owner) <= 200)),
    lease_expires_at         timestamptz,
    attempt_count            integer NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    record_count             integer CHECK (record_count IS NULL OR (record_count >= 0)),
    raw_sha256               text CHECK (raw_sha256 IS NULL OR (length(raw_sha256) <= 64)),
    lake_run_id              text CHECK (lake_run_id IS NULL OR (length(lake_run_id) <= 200)),
    lake_manifest_key        text CHECK (lake_manifest_key IS NULL OR (length(lake_manifest_key) <= 512)),
    lake_raw_object_key      text CHECK (lake_raw_object_key IS NULL OR (length(lake_raw_object_key) <= 512)),
    lake_bronze_object_key   text CHECK (lake_bronze_object_key IS NULL OR (length(lake_bronze_object_key) <= 512)),
    error_code               text CHECK (error_code IS NULL OR (length(error_code) <= 80)),
    error_message            text CHECK (error_message IS NULL OR (length(error_message) <= 500)),
    verified_at              timestamptz,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, intake_key),
    UNIQUE (workspace_id, idempotency_key),
    FOREIGN KEY (workspace_id, source_id) REFERENCES intake.sources (workspace_id, id)
);
CREATE UNIQUE INDEX intakes_legacy ON intake.intakes (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX intakes_dataset ON intake.intakes (workspace_id, dataset);
CREATE INDEX intakes_domain ON intake.intakes (workspace_id, domain);
CREATE INDEX intakes_idempotency_key ON intake.intakes (workspace_id, idempotency_key);
CREATE INDEX intakes_intake_key ON intake.intakes (workspace_id, intake_key);
CREATE INDEX intakes_lease_owner ON intake.intakes (workspace_id, lease_owner);
CREATE INDEX intakes_source_id ON intake.intakes (workspace_id, source_id);
CREATE INDEX intakes_status ON intake.intakes (workspace_id, status);

CREATE TABLE intake.intake_events (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    intake_id                bigint NOT NULL,
    event_type               text NOT NULL CHECK (event_type IN ('queued', 'claimed', 'lease_renewed', 'landed', 'verified', 'rejected', 'failed', 'retried', 'cancelled')),
    actor                    text NOT NULL DEFAULT 'system' CHECK (length(actor) <= 80),
    from_status              text CHECK (from_status IS NULL OR (length(from_status) <= 32)),
    to_status                text NOT NULL CHECK (length(to_status) <= 32 AND length(to_status) >= 1),
    reason                   text CHECK (reason IS NULL OR (length(reason) <= 500)),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    FOREIGN KEY (workspace_id, intake_id) REFERENCES intake.intakes (workspace_id, id)
);
CREATE UNIQUE INDEX intake_events_legacy ON intake.intake_events (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX intake_events_event_type ON intake.intake_events (workspace_id, event_type);
CREATE INDEX intake_events_intake_id ON intake.intake_events (workspace_id, intake_id);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE intake.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('source', 'intake', 'intake-event')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE intake.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON intake.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['sources', 'intakes', 'intake_events', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE intake.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE intake.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON intake.%I'
                       ' USING (workspace_id = intake.current_workspace())'
                       ' WITH CHECK (workspace_id = intake.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA intake TO intake_api;
GRANT EXECUTE ON FUNCTION intake.current_workspace() TO intake_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON intake.sources, intake.intakes, intake.intake_events TO intake_api;
GRANT USAGE ON SEQUENCE intake.sources_id_seq, intake.intakes_id_seq, intake.intake_events_id_seq TO intake_api;
GRANT SELECT, INSERT ON intake.create_keys TO intake_api;
GRANT SELECT, INSERT ON intake.outbox TO intake_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON intake.outbox TO intake_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON intake.outbox TO intake_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA intake TO intake_publisher;
GRANT SELECT ON intake.outbox TO intake_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON intake.outbox TO intake_publisher;
